@namespace sv_da8713a9a6d24ab89a7c9cb6c613a036.Components.Pages.ApplySteps

<nav class="step-indicator mb-4" aria-label="Application steps">
    <ol class="d-flex list-unstyled justify-content-between p-0 m-0 position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var state = step < CurrentStep ? "completed"
                      : step == CurrentStep ? "active"
                      : "future";
            <li class="step-item text-center flex-fill @state"
                role="listitem">
                @if (step < CurrentStep)
                {
                    <button class="btn btn-link p-0 text-decoration-none w-100"
                            @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-circle completed-circle">&#10003;</span>
                        <span class="step-label d-block small mt-1">@StepNames[step]</span>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(step == CurrentStep ? "active-circle" : "future-circle")">@(step + 1)</span>
                        <span class="step-label d-block small mt-1">@StepNames[step]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    public static readonly string[] StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }
}

@using sv_da8713a9a6d24ab89a7c9cb6c613a036.Services
@namespace sv_da8713a9a6d24ab89a7c9cb6c613a036.Components.Pages.ApplySteps

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
    <input id="fullName" class="form-control" @bind="State.FullName" />
</div>

<div class="mb-3">
    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
    <input id="email" type="email" class="form-control" @bind="State.Email" />
    @if (!string.IsNullOrEmpty(_emailError))
    {
        <div class="text-danger small mt-1">@_emailError</div>
    }
</div>

<div class="mb-3">
    <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
    <input id="phone" type="tel" class="form-control" @bind="State.Phone" />
</div>

<div class="mb-3">
    <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
    <textarea id="address" class="form-control" rows="2" @bind="State.Address"></textarea>
</div>

@if (!string.IsNullOrEmpty(_validationError))
{
    <div class="alert alert-danger">@_validationError</div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="NextAsync" disabled="@_validating">
        @if (_validating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? _validationError;
    private string? _emailError;
    private bool _validating;

    private async Task NextAsync()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(State.FullName) ||
            string.IsNullOrWhiteSpace(State.Email) ||
            string.IsNullOrWhiteSpace(State.Phone) ||
            string.IsNullOrWhiteSpace(State.Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        _validating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(State.Email);
            if (!emailValid)
            {
                _emailError = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            _validating = false;
        }

        await OnNext.InvokeAsync();
    }
}

