@using sv_da8713a9a6d24ab89a7c9cb6c613a036.Services
@namespace sv_da8713a9a6d24ab89a7c9cb6c613a036.Components.Pages.ApplySteps

<h4 class="mb-3">Work History</h4>

@for (int idx = 0; idx < State.WorkEntries.Count; idx++)
{
    var entry = State.WorkEntries[idx];
    var index = idx;
    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (State.WorkEntries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Company" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Title" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="current-@index" @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (!string.IsNullOrEmpty(_validationError))
{
    <div class="alert alert-danger">@_validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="Next">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void AddEntry() => State.WorkEntries.Add(new WorkEntryState());

    private void RemoveEntry(int index) => State.WorkEntries.RemoveAt(index);

    private async Task Next()
    {
        _validationError = null;
        foreach (var e in State.WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title))
            {
                _validationError = "Company and Job Title are required for every position.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_da8713a9a6d24ab89a7c9cb6c613a036.Services
@namespace sv_da8713a9a6d24ab89a7c9cb6c613a036.Components.Pages.ApplySteps

<h4 class="mb-3">References</h4>

@for (int idx = 0; idx < State.References.Count; idx++)
{
    var refEntry = State.References[idx];
    var index = idx;
    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (State.References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="refEntry.Name" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="refEntry.Relationship" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="refEntry.Email" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="refEntry.Phone" />
                </div>
            </div>
        </div>
    </div>
}

@if (State.References.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

@if (!string.IsNullOrEmpty(_validationError))
{
    <div class="alert alert-danger">@_validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="Next">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void AddReference()
    {
        if (State.References.Count < 3)
            State.References.Add(new ReferenceState());
    }

    private void RemoveReference(int index) => State.References.RemoveAt(index);

    private async Task Next()
    {
        _validationError = null;
        foreach (var r in State.References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) ||
                string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All fields are required for every reference.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

