@using sv_da8713a9a6d24ab89a7c9cb6c613a036.Services
@namespace sv_da8713a9a6d24ab89a7c9cb6c613a036.Components.Pages.ApplySteps

@if (_submitted)
{
    <div class="text-center py-5">
        <div class="mb-3">
            <span class="text-success" style="font-size:3rem;">&#10003;</span>
        </div>
        <h3>Application Submitted!</h3>
        <p class="lead">Your application ID is <strong>#@_applicationId</strong>.</p>
        <p>Thank you for applying. We will be in touch soon.</p>
    </div>
}
else
{
    <h4 class="mb-3">Review &amp; Submit</h4>

    @* Personal Info *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick='() => OnEditStep.InvokeAsync(0)'>Edit</button>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@State.FullName</dd>
                <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@State.Email</dd>
                <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@State.Phone</dd>
                <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@State.Address</dd>
            </dl>
        </div>
    </div>

    @* Work History *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick='() => OnEditStep.InvokeAsync(1)'>Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in State.WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom">
                    <h6>@entry.Title at @entry.Company</h6>
                    <p class="text-muted small mb-1">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </p>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>

    @* References *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick='() => OnEditStep.InvokeAsync(2)'>Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in State.References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    <span class="text-muted">@r.Email &middot; @r.Phone</span>
                </div>
            }
        </div>
    </div>

    @* Cover Letter *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick='() => OnEditStep.InvokeAsync(3)'>Edit</button>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@State.CoverLetter</p>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(_submitError))
    {
        <div class="alert alert-danger">@_submitError</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-success btn-lg" @onclick="SubmitAsync" disabled="@_submitting">
            @if (_submitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Submit Application
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _submitError;

    private async Task SubmitAsync()
    {
        _submitting = true;
        _submitError = null;
        try
        {
            _applicationId = await ApplicationService.SubmitApplicationAsync(State.ToJobApplication());
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _submitting = false;
        }
    }
}

