@page "/apply"
@using sv_da8713a9a6d24ab89a7c9cb6c613a036.Components.Pages.ApplySteps
@using sv_da8713a9a6d24ab89a7c9cb6c613a036.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep State="_state" OnNext="NextStep" ApplicationService="ApplicationService" />
            break;
        case 1:
            <WorkHistoryStep State="_state" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep State="_state" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep State="_state" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep State="_state" OnBack="PreviousStep" OnEditStep="GoToStep"
                        ApplicationService="ApplicationService" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private readonly ApplicationFormState _state = new();

    private void NextStep() => _currentStep++;

    private void PreviousStep() => _currentStep--;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
            _currentStep = step;
    }
}

::deep .step-indicator ol {
    counter-reset: step;
}

::deep .step-indicator ol::before {
    content: "";
    position: absolute;
    top: 18px;
    left: 10%;
    right: 10%;
    height: 2px;
    background: #dee2e6;
    z-index: 0;
}

::deep .step-item {
    position: relative;
    z-index: 1;
}

::deep .step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .completed-circle {
    background-color: #198754;
    color: white;
}

::deep .active-circle {
    background-color: #0d6efd;
    color: white;
}

::deep .future-circle {
    background-color: #e9ecef;
    color: #6c757d;
}

::deep .step-label {
    font-size: 0.75rem;
    color: #6c757d;
}

::deep .step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

::deep .step-item.completed .step-label {
    color: #198754;
}

